// Dualray Fast (prototype): an approximate, cache-free constant-L/h gamut
// mapper for OKLCh input. Standalone: it needs only the conversion matrices,
// the transfer function and its fitted hue polynomials.
//
// Along a constant-hue ray, each linear channel divided by L³ is a cubic in
// u = C/L. Below the cusp the first exit is on the lower face: one channel is
// zero and the other two are L³·g_k(h), where g_k and the boundary ratio
// depend on hue only. Per-sector hue polynomials (generated by
// scripts/generate-dualray-fast.mjs from exact roots) give them directly, so
// most out-of-gamut colors need no trig, no conversion and no solve.
//
// 1. Shortcut: chroma at or beyond the fitted ratio plus a margin that bounds
//    the sampled ratio from above (never an in-gamut color), and both fitted
//    channels at most one (below the cusp).
// 2. Otherwise convert canonically; an in-gamut color returns that conversion
//    unchanged, including colors in a blue-fold window's re-entry island.
// 3. Out of gamut below the cusp (the margin band): the shortcut's output.
// 4. Above the cusp: the chord seed and Householder steps on the brighter
//    lower channel, retried on a channel that exceeds one.
// 5. Anything else (blue-fold windows, rejected upper solves, neutrals):
//    the first exit by bisection between the channels' stationary points.
//
// Accuracy is an empirical ΔEOK budget, not a bound: the channel fits target
// 1e-4 against a 1e-3 max / 1e-4 p99 runtime target. FAST_ENCODE swaps the
// transfer function's pow for a polynomial on out-of-gamut results only.

use super::color::{KA0, KA1, KA2, KB0, KB1, KB2};
use super::dualray::first_exit;
use super::gamut::{DisplayP3, Rec2020, RgbGamut, Srgb};
use super::transfer::TransferFunction;
use super::{Float, PI, SINGLE};
use crate::rgb_spaces::SpaceId;

// Shared by every target's generated data.
const U_TERMS: usize = p3::U_TERMS;
const G_TERMS: usize = p3::G_TERMS;

pub(crate) trait DualrayFastData: RgbGamut {
    const BLUE_START: Float;
    const RED_START: Float;
    const RED_END: Float;
    const GREEN_START: Float;
    const RED_FOLD: Float;
    // The fold hue's rounding remainder: RED_FOLD + RED_FOLD_LO is binary64.
    const RED_FOLD_LO: Float;
    const SCALE: [Float; 3];
    const OFFSET: [Float; 3];
    const MARGIN: [Float; 3];
    const U: [[Float; U_TERMS]; 3];
    const G0: [[Float; G_TERMS]; 3];
    const G1: [[Float; G_TERMS]; 3];
}

const fn narrow<const N: usize>(input: [f64; N]) -> [Float; N] {
    let mut out = [0.0; N];
    let mut i = 0;
    while i < N {
        out[i] = input[i] as Float;
        i += 1;
    }
    out
}
const fn narrow_rows<const N: usize>(input: [[f64; N]; 3]) -> [[Float; N]; 3] {
    [narrow(input[0]), narrow(input[1]), narrow(input[2])]
}

macro_rules! fitted {
    ($gamut:ty, $module:ident, $file:literal) => {
        mod $module {
            include!($file);
        }
        // Every target's data shares the term counts.
        const _: () = assert!($module::U_TERMS == U_TERMS && $module::G_TERMS == G_TERMS);
        impl DualrayFastData for $gamut {
            const BLUE_START: Float = $module::BLUE_START as Float;
            const RED_START: Float = $module::RED_START as Float;
            const RED_END: Float = $module::RED_END as Float;
            const GREEN_START: Float = $module::GREEN_START as Float;
            const RED_FOLD: Float = $module::RED_FOLD as Float;
            const RED_FOLD_LO: Float =
                ($module::RED_FOLD - ($module::RED_FOLD as Float) as f64) as Float;
            const SCALE: [Float; 3] = narrow($module::SCALE);
            const OFFSET: [Float; 3] = narrow($module::OFFSET);
            const MARGIN: [Float; 3] = narrow($module::MARGIN);
            const U: [[Float; U_TERMS]; 3] = narrow_rows($module::U);
            const G0: [[Float; G_TERMS]; 3] = narrow_rows($module::G0);
            const G1: [[Float; G_TERMS]; 3] = narrow_rows($module::G1);
        }
    };
}
fitted!(Srgb, srgb, "generated/dualray_fast_srgb.rs");
fitted!(DisplayP3, p3, "generated/dualray_fast_display_p3.rs");
fitted!(Rec2020, rec2020, "generated/dualray_fast_rec2020.rs");

// Hardware FMA when the target has it; otherwise a separate multiply/add.
#[inline(always)]
fn fma(a: Float, b: Float, c: Float) -> Float {
    #[cfg(target_feature = "fma")]
    {
        a.mul_add(b, c)
    }
    #[cfg(not(target_feature = "fma"))]
    {
        a * b + c
    }
}

// Grouped powers (Estrin): short dependency chains for these latency-bound fits.
#[inline(always)]
fn estrin<const N: usize>(p: &[Float; N], t: Float) -> Float {
    let mut level = [0.0 as Float; 16];
    let mut n = 0;
    let mut i = 0;
    while i < N {
        level[n] = if i + 1 < N {
            fma(p[i + 1], t, p[i])
        } else {
            p[i]
        };
        n += 1;
        i += 2;
    }
    let mut x = t * t;
    while n > 1 {
        let mut j = 0;
        let mut k = 0;
        while j < n {
            level[k] = if j + 1 < n {
                fma(level[j + 1], x, level[j])
            } else {
                level[j]
            };
            k += 1;
            j += 2;
        }
        n = k;
        x = x * x;
    }
    level[0]
}

// x^(5/12) for normal x in (0, 1]: x = m·2^e with e = 12q + r, so
// x^(5/12) = m^(5/12) · 2^(5q) · 2^(5r/12). Degree-5 Chebyshev-derived
// polynomial for m in [1, 2): 1.8e-6 relative, about 1.9e-6 encoded.
// Each lane splits its own float format: the f32 lane is pure f32.
const TWELFTHS: [f64; 12] = [
    1.0,
    1.3348398541700344,
    1.7817974362806785,
    2.378414230005442,
    3.174802103936399,
    4.237852377437181,
    5.656854249492381,
    7.550994501453547,
    10.079368399158986,
    13.454342644059432,
    17.959392772949972,
    23.9729132300269,
];
const TWELFTHS_F32: [f32; 12] = {
    let mut out = [0.0; 12];
    let mut i = 0;
    while i < 12 {
        out[i] = TWELFTHS[i] as f32;
        i += 1;
    }
    out
};
#[inline(always)]
fn mantissa_power(m: Float) -> Float {
    let t = 2.0 * m - 3.0;
    let t2 = t * t;
    (1.1840522979550885 + 0.16445223215860819 * t)
        + t2 * (-0.015965263486395525 + 0.0028065866056053617 * t)
        + t2 * t2 * (-0.0006657143993239837 + 0.00016073400297855756 * t)
}
#[inline(always)]
fn pow_5_12(x: Float) -> Float {
    if SINGLE {
        let bits = (x as f32).to_bits();
        let e = ((bits >> 23) as i32) - 127;
        let m = f32::from_bits((bits & 0x007f_ffff) | 0x3f80_0000) as Float;
        let (q, r) = (e.div_euclid(12), e.rem_euclid(12));
        let scale = f32::from_bits(((127 + 5 * q) as u32) << 23) * TWELFTHS_F32[r as usize];
        mantissa_power(m) * scale as Float
    } else {
        let bits = (x as f64).to_bits();
        let e = ((bits >> 52) as i64) - 1023;
        let m = f64::from_bits((bits & 0x000f_ffff_ffff_ffff) | 0x3ff0_0000_0000_0000) as Float;
        let (q, r) = (e.div_euclid(12), e.rem_euclid(12));
        let scale = f64::from_bits(((1023 + 5 * q) as u64) << 52) * TWELFTHS[r as usize];
        mantissa_power(m) * scale as Float
    }
}
#[inline(always)]
fn encode_fast<G: DualrayFastData>(x: Float) -> Float {
    let x = x.clamp(0.0, 1.0);
    let y = if G::ID == SpaceId::Rec2020 {
        if x < Float::MIN_POSITIVE {
            0.0
        } else {
            pow_5_12(x)
        }
    } else if x <= 0.0031308 {
        12.92 * x
    } else {
        1.055 * pow_5_12(x) - 0.055
    };
    // The polynomial's error can exceed one just below x = 1.
    y.min(1.0)
}

// Relative residual and face guards for the approximate upper solve.
const UPPER_TOLERANCE: Float = if SINGLE { 64.0 * Float::EPSILON } else { 1e-7 };

// Which path mapped a color (diagnostics; `map` discards it).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Path {
    Endpoint,
    Lower,
    Inside,
    MarginBand,
    Upper,
    UpperRetry,
    Search,
}

// Why the shortcut declined.
enum Decline {
    // A hue the fits do not cover (a blue-fold window).
    Uncovered,
    // Chroma below the fitted ratio plus margin: inside, the margin band, or
    // above the cusp.
    BelowRatio {
        sector: usize,
        t: Float,
        root: Float,
    },
    // Beyond the lower boundary and above the cusp: outside via an upper face.
    AboveCusp {
        sector: usize,
        root: Float,
        g: [Float; 2],
    },
}

// Nonzero channels of each sector, in increasing order; the third is zero.
const NONZERO: [[usize; 2]; 3] = [[0, 1], [1, 2], [0, 2]];

// Channel cubic along the ray, divided by L³: ((d·u + b)·u + a)·u + r, where
// r is the matrix row sum (the neutral's value).
#[inline(always)]
fn value([d, b, a, r]: [Float; 4], u: Float) -> Float {
    ((d * u + b) * u + a) * u + r
}

// The three channel cubics at the input hue, from the canonical conversion's
// matrices: channel_k / L³ = Σ_j M[k][j]·(1 + u·κ_j)³.
#[inline(always)]
fn cubics<G: DualrayFastData>(h: Float) -> [[Float; 4]; 3] {
    let (b, a) = (h * (PI / 180.0)).sin_cos();
    let k = [KA0 * a + KB0 * b, KA1 * a + KB1 * b, KA2 * a + KB2 * b];
    let k2 = k.map(|x| x * x);
    let k3 = [k2[0] * k[0], k2[1] * k[1], k2[2] * k[2]];
    G::LMS_TO_RGB.map(|m| {
        [
            m[0] * k3[0] + m[1] * k3[1] + m[2] * k3[2],
            3.0 * (m[0] * k2[0] + m[1] * k2[1] + m[2] * k2[2]),
            3.0 * (m[0] * k[0] + m[1] * k[1] + m[2] * k[2]),
            m[0] + m[1] + m[2],
        ]
    })
}

// Slack for the red channel's floor near its fold (see `search`).
const FOLD_SLACK: Float = 32.0 * Float::EPSILON;

pub(crate) struct DualrayFast<G: DualrayFastData, const FAST_ENCODE: bool = false>(
    std::marker::PhantomData<G>,
);

impl<G: DualrayFastData, const FAST_ENCODE: bool> DualrayFast<G, FAST_ENCODE> {
    pub(crate) fn new() -> Self {
        Self(std::marker::PhantomData)
    }

    #[inline(always)]
    fn encode(x: Float) -> Float {
        if FAST_ENCODE {
            encode_fast::<G>(x)
        } else {
            G::Transfer::encode_clamped(x)
        }
    }

    // Lower-face output: the sector's zero channel and two fitted channels.
    #[inline(always)]
    fn lower(sector: usize, x: [Float; 2], out: &mut [Float; 3]) {
        *out = [0.0; 3];
        let [i, j] = NONZERO[sector];
        out[i] = Self::encode(x[0]);
        out[j] = Self::encode(x[1]);
    }

    // The shortcut, at a hue in [0, 360).
    #[inline(always)]
    fn shortcut(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> Result<(), Decline> {
        let (sector, v) = if h >= G::BLUE_START && h < G::RED_START {
            (0, h)
        } else if h >= G::RED_START && h < G::RED_END {
            (1, (G::RED_FOLD - h).sqrt())
        } else if h > G::GREEN_START && h < 360.0 {
            // Strict: the blue-fold window includes its upper endpoint.
            (2, h)
        } else if h >= 0.0 && h < G::BLUE_START {
            (2, h + 360.0)
        } else {
            return Err(Decline::Uncovered);
        };
        let t = fma(G::SCALE[sector], v, G::OFFSET[sector]);
        let root = estrin(&G::U[sector], t);
        if !(c >= (root + G::MARGIN[sector]) * l) {
            return Err(Decline::BelowRatio { sector, t, root });
        }
        let l3 = l * l * l;
        let g = [estrin(&G::G0[sector], t), estrin(&G::G1[sector], t)];
        if !(l3 * g[0] <= 1.0 && l3 * g[1] <= 1.0) {
            return Err(Decline::AboveCusp { sector, root, g });
        }
        Self::lower(sector, g.map(|x| l3 * x), out);
        Ok(())
    }

    // Above the cusp: Dualray's chord seed and two Householder steps on the
    // chosen face, from the fitted lower root and channel value. If another
    // channel exceeds one there, that channel exits first: retry on it.
    #[inline(always)]
    fn upper(
        l: Float,
        c: Float,
        rows: &[[Float; 4]; 3],
        root: Float,
        mut face: usize,
        lower: Float,
        out: &mut [Float; 3],
    ) -> Option<Path> {
        let inv_l = 1.0 / l;
        let target = inv_l * inv_l * inv_l;
        let guard = target * (1.0 + UPPER_TOLERANCE);
        let mut u = root * (target - 1.0) / (lower - 1.0);
        for attempt in 0..3 {
            let [d, b, a, r] = rows[face];
            for _ in 0..2 {
                // Reuse Horner intermediates for f, f' and f''/2.
                let du = d * u;
                let q = du + b;
                let p = q * u + a;
                let f = (p * u + r) - target;
                let half_second = (du + du) + q;
                let f1 = (du + q) * u + p;
                let f1_squared = f1 * f1;
                let product = f * half_second;
                let denominator = f1 * (f1_squared - 2.0 * product) + f * f * d;
                if denominator == 0.0 {
                    return None;
                }
                u -= f * (f1_squared - product) / denominator;
            }
            let values = rows.map(|row| value(row, u));
            if !(u >= 0.0
                && u * l < c
                && (values[face] - target).abs() <= target * UPPER_TOLERANCE
                && values.iter().all(|&v| v >= -UPPER_TOLERANCE))
            {
                return None;
            }
            let brightest = if values[0] >= values[1] && values[0] >= values[2] {
                0
            } else if values[1] >= values[2] {
                1
            } else {
                2
            };
            if values[brightest] > guard && brightest != face {
                face = brightest;
                continue;
            }
            let l3 = l * l * l;
            *out = std::array::from_fn(|k| {
                if k == face {
                    1.0
                } else {
                    Self::encode(l3 * values[k])
                }
            });
            return Some(if attempt == 0 {
                Path::Upper
            } else {
                Path::UpperRetry
            });
        }
        None
    }

    // The exact first exit, for colors the fast paths do not cover.
    //
    // Whether the red channel's dip crosses zero depends only on hue and
    // changes at the red fold, where the dip is tangent and lane rounding
    // cannot decide it (f32 picked the wrong exit at Rec.2020's fold). The
    // binary64 fold hue decides instead: before it a dip within FOLD_SLACK of
    // zero is an exit, after it a dip within FOLD_SLACK is not.
    fn search(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> Path {
        let rows = cubics::<G>(h);
        let inv_l = 1.0 / l;
        let target = inv_l * inv_l * inv_l;
        let before_fold = h < G::RED_FOLD || (h == G::RED_FOLD && G::RED_FOLD_LO > 0.0);
        let red_floor = if before_fold { FOLD_SLACK } else { -FOLD_SLACK };
        let (u, beyond) = first_exit(&rows, [0.0; 3], target, (c * inv_l).max(0.0), red_floor);
        let l3 = l * l * l;
        *out = rows.map(|row| Self::encode(l3 * value(row, u)));
        // Write the exiting channel exactly on its face.
        if let Some(hi) = beyond {
            let at = rows.map(|row| value(row, hi));
            let floor = |k: usize| if k == 0 { red_floor } else { 0.0 };
            if let Some(k) = (0..3).find(|&k| at[k] < floor(k) || at[k] > target) {
                out[k] = if at[k] > target { 1.0 } else { 0.0 };
            }
        }
        Path::Search
    }

    // The canonical conversion, at the authored hue: true (with the
    // conversion written) when it is in gamut.
    #[inline(always)]
    fn inside(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> bool {
        let rgb = super::color::Oklch::from([l, c, h])
            .to_oklab()
            .to_linear_rgb::<G>();
        if rgb.in_gamut() {
            *out = rgb.encode_clamped().channels;
        }
        rgb.in_gamut()
    }

    pub(crate) fn map_path(oklch: &[Float; 3], out: &mut [Float; 3]) -> Path {
        let [l, c, h] = *oklch;
        if !(l > 0.0 && l < 1.0) {
            *out = [if l >= 1.0 { 1.0 } else { 0.0 }; 3];
            return Path::Endpoint;
        }
        let c = c.max(0.0);
        let in_range = h >= 0.0 && h < 360.0;
        let hue = if in_range { h } else { h.rem_euclid(360.0) };
        // The fits need the reduced hue, but the canonical conversion uses
        // the authored one, and for a large f64 hue the two round to
        // directions degrees apart. Check membership first, so the shortcut
        // cannot claim a canonically in-gamut color.
        if !in_range && Self::inside(l, c, h, out) {
            return Path::Inside;
        }
        let decline = match Self::shortcut(l, c, hue, out) {
            Ok(()) => return Path::Lower,
            Err(decline) => decline,
        };
        // Above the cusp beyond the lower boundary is always out of gamut.
        if in_range && !matches!(decline, Decline::AboveCusp { .. }) && Self::inside(l, c, h, out) {
            return Path::Inside;
        }
        let (sector, root, g) = match decline {
            Decline::Uncovered => return Self::search(l, c, hue, out),
            Decline::AboveCusp { sector, root, g } => (sector, root, g),
            Decline::BelowRatio { sector, t, root } => {
                let g = [estrin(&G::G0[sector], t), estrin(&G::G1[sector], t)];
                (sector, root, g)
            }
        };
        let l3 = l * l * l;
        if l3 * g[0] <= 1.0 && l3 * g[1] <= 1.0 {
            // Out of gamut below the cusp (the margin band): the lower face.
            // For an out-of-range hue, "out of gamut" was decided at the
            // authored direction; search the reduced one instead.
            if !in_range {
                return Self::search(l, c, hue, out);
            }
            Self::lower(sector, g.map(|x| l3 * x), out);
            return Path::MarginBand;
        }
        // The brighter channel at the lower root is the likely upper face.
        let brighter = (g[1] > g[0]) as usize;
        let rows = cubics::<G>(hue);
        match Self::upper(
            l,
            c,
            &rows,
            root,
            NONZERO[sector][brighter],
            g[brighter],
            out,
        ) {
            Some(path) => path,
            None => Self::search(l, c, hue, out),
        }
    }

    // Diagnostics: the path a color takes.
    #[allow(dead_code)] // Used by the dualray-fast example.
    pub(crate) fn path(oklch: &[Float; 3]) -> Path {
        Self::map_path(oklch, &mut [0.0; 3])
    }

    #[inline(always)]
    pub(crate) fn map(&mut self, oklch: &[Float; 3], out: &mut [Float; 3]) {
        Self::map_path(oklch, out);
    }

    // The canonical precheck is part of the method: both modes are identical.
    #[inline(always)]
    pub(crate) fn map_with_in_gamut_check(&mut self, oklch: &[Float; 3], out: &mut [Float; 3]) {
        self.map(oklch, out);
    }
}

// The same method with the polynomial transfer function (separate benchmark row).
pub(crate) type DualrayFastEncode<G> = DualrayFast<G, true>;

#[cfg(test)]
mod tests {
    use super::*;

    // Out-of-range authored hues: a canonically in-gamut color passes through
    // bit for bit, whatever direction the reduced hue gives the fits.
    fn preserves_in_gamut<G: DualrayFastData>() {
        let mut fast = DualrayFast::<G>::new();
        let hues = [
            -1e300,
            -1e16,
            -720.25,
            -95.947975,
            -0.0,
            360.0,
            1e7,
            1e12,
            10000000000005742.0,
            3.0e38,
            1e300,
        ];
        // Casting to f32 overflows the largest to infinity, outside the domain.
        for h in hues
            .map(|x: f64| x as Float)
            .into_iter()
            .filter(|h| h.is_finite())
        {
            for li in 1..40 {
                for ci in 0..40 {
                    let input = [li as Float / 40.0, ci as Float * 0.01, h];
                    let rgb = super::super::color::Oklch::from(input)
                        .to_oklab()
                        .to_linear_rgb::<G>();
                    let mut out = [0.0; 3];
                    fast.map(&input, &mut out);
                    assert!(
                        out.iter().all(|v| v.is_finite() && (0.0..=1.0).contains(v)),
                        "{input:?}: {out:?}"
                    );
                    if rgb.in_gamut() {
                        assert_eq!(
                            out.map(Float::to_bits),
                            rgb.encode_clamped().channels.map(Float::to_bits),
                            "{} {input:?}",
                            G::DEFINITION.name
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn out_of_range_hues_keep_canonical_in_gamut_colors() {
        preserves_in_gamut::<Srgb>();
        preserves_in_gamut::<DisplayP3>();
        preserves_in_gamut::<Rec2020>();
        // Review reproducer: f64 reduction gives 262 degrees, the canonical
        // direction differs, and the shortcut claimed an in-gamut color.
        if !SINGLE {
            let input = [0.5, 0.3, 10000000000005742.0 as Float];
            let rgb = super::super::color::Oklch::from(input)
                .to_oklab()
                .to_linear_rgb::<DisplayP3>();
            assert!(rgb.in_gamut());
            let mut out = [0.0; 3];
            DualrayFast::<DisplayP3>::new().map(&input, &mut out);
            assert_eq!(out, rgb.encode_clamped().channels);
        }
    }
}
